// Bank configuration fields within a template manifest.
//
// Only includes configurable (per-bank) fields. Credential fields (API keys, base URLs) are
// intentionally excluded for security.
// Ref: #/components/schemas/BankTemplateConfig
type BankTemplateConfig struct {
	// Mission/context for Reflect operations.
	ReflectMission OptString `json:"reflect_mission"`
	// Steers what gets extracted during retain.
	RetainMission OptString `json:"retain_mission"`
	// Fact extraction mode: 'concise' (default), 'verbose', 'custom', 'verbatim', or 'chunks'.
	RetainExtractionMode OptString `json:"retain_extraction_mode"`
	// Custom extraction prompt (when mode='custom').
	RetainCustomInstructions OptString `json:"retain_custom_instructions"`
	// Target max characters for each content chunk.
	RetainChunkSize OptInt `json:"retain_chunk_size"`
	// Max characters for a single JSONL line or conversation turn to keep whole; defaults to
	// retain_chunk_size when unset.
	RetainStructuredChunkSize OptInt `json:"retain_structured_chunk_size"`
	// Toggle observation consolidation.
	EnableObservations OptBool `json:"enable_observations"`
	// Controls what gets synthesised.
	ObservationsMission OptString `json:"observations_mission"`
	// Toggle the keyword (BM25) arm during recall, leaving pure vector search.
	EnableTextSearch OptBool `json:"enable_text_search"`
	// Toggle the temporal arm (and its date-aware query analysis) during recall.
	EnableTemporalRetrieval OptBool `json:"enable_temporal_retrieval"`
	// Toggle the entity/link graph arm during recall.
	EnableGraphRetrieval OptBool `json:"enable_graph_retrieval"`
	// Toggle cross-encoder reranking during recall.
	EnableReranking OptBool `json:"enable_reranking"`
	// Skepticism trait (1-5).
	DispositionSkepticism OptInt `json:"disposition_skepticism"`
	// Literalism trait (1-5).
	DispositionLiteralism OptInt `json:"disposition_literalism"`
	// Empathy trait (1-5).
	DispositionEmpathy OptInt `json:"disposition_empathy"`
	// Controlled vocabulary for entity labels.
	EntityLabels []LabelGroupOutput `json:"entity_labels"`
	// Allow entities outside the label vocabulary.
	EntitiesAllowFreeForm OptBool `json:"entities_allow_free_form"`
	// Name of the default retain strategy (key into retain_strategies map).
	RetainDefaultStrategy OptString `json:"retain_default_strategy"`
	// Map of retain strategy name to per-strategy config dict.
	RetainStrategies OptBankTemplateConfigRetainStrategies `json:"retain_strategies"`
	// Max chunks per streaming batch (0 disables batching).
	RetainChunkBatchSize OptInt `json:"retain_chunk_batch_size"`
	// Hard cap on inline images in a single extraction chunk.
	RetainMaxAttachmentsPerChunk OptInt `json:"retain_max_attachments_per_chunk"`
	// MCP tool allowlist for this bank (None = all tools).
	McpEnabledTools []string `json:"mcp_enabled_tools"`
	// LLM batch size for observation consolidation.
	ConsolidationLlmBatchSize OptInt `json:"consolidation_llm_batch_size"`
	// Max tokens of source facts per consolidation batch.
	ConsolidationSourceFactsMaxTokens OptInt `json:"consolidation_source_facts_max_tokens"`
	// Max tokens of source facts per observation.
	ConsolidationSourceFactsMaxTokensPerObservation OptInt `json:"consolidation_source_facts_max_tokens_per_observation"`
	// Max observations to retain per consolidation scope.
	MaxObservationsPerScope OptInt `json:"max_observations_per_scope"`
	// DEPRECATED — use consolidation_strategies, which carries the mission too. Still honoured, but
	// consulted only after consolidation_strategies. Per-scope overrides of max_observations_per_scope:
	// [{"scope": ["run_*", "shared"], "limit": 1}]. Each scope is a list of fnmatch tag-globs; a
	// consolidation scope matches under exact cover (every tag matched by a glob and every glob matched by
	// a tag). The first matching rule wins; unmatched scopes fall back to max_observations_per_scope.
	ObservationScopeLimits []BankTemplateConfigObservationScopeLimitsItem `json:"observation_scope_limits"`
	// Per-scope consolidation settings: [{"scopes": [{"tags": ["company:*"]}], "observations_mission":
	// "Record only generalized trends.", "max_observations_per_scope": 20}]. Each strategy lists the rules
	// it claims scopes with — a rule's tags are fnmatch globs that must all be on the scope, and its
	// "tags_match" decides whether the scope may carry others ("all", the default) or not ("exact"). The
	// rules are alternatives: any one matching claims the scope. A strategy may set any of
	// observations_mission, max_observations_per_scope, consolidation_source_facts_max_tokens and
	// consolidation_source_facts_max_tokens_per_observation; each is optional. Exactly one strategy
	// applies to a scope: the first in the list that claims it. Whatever that strategy leaves unset —
	// and every scope no strategy claims — uses the bank-wide value; a later strategy never fills the
	// gaps. Supersedes observation_scope_limits. Lets one bank be federated across user/team/company tag
	// scopes, each consolidating under its own brief.
	ConsolidationStrategies []ConsolidationStrategySpec `json:"consolidation_strategies"`
	// Max tokens of source facts per reflect call.
	ReflectSourceFactsMaxTokens OptInt `json:"reflect_source_facts_max_tokens"`
	// Trigger fields merged over the built-in knowledge-page default when a page is created (e.g.
	// {"refresh_cron": "0 * * * *"}). A trigger sent with the create request still wins.
	KnowledgePageDefaultTrigger OptBankTemplateConfigKnowledgePageDefaultTrigger `json:"knowledge_page_default_trigger"`
	// Default reflect options for this bank (e.g. {"reflect_search_observations_max_tokens": 3000,
	// "reflect_search_observations_include_entities": false}). Applied to every reflect in the bank --
	// API, MCP and mental-model refresh -- whenever the request (or the model's trigger) leaves the option
	// unset.
	ReflectDefaultOptions OptBankTemplateConfigReflectDefaultOptions `json:"reflect_default_options"`
	// Minimum seconds between two automatic refreshes of the same mental model in this bank. 0 (the
	// default) means no floor. Overridable per model via the trigger's min_refresh_interval_seconds.
	MentalModelMinRefreshIntervalSeconds OptInt `json:"mental_model_min_refresh_interval_seconds"`
	// Per-bank Gemini/VertexAI safety filter settings.
	LlmGeminiSafetySettings []jx.Raw `json:"llm_gemini_safety_settings"`
	// Recall budget mapping function: 'fixed' or 'adaptive'.
	RecallBudgetFunction OptString `json:"recall_budget_function"`
	// Fixed thinking_budget for budget=low (function='fixed').
	RecallBudgetFixedLow OptInt `json:"recall_budget_fixed_low"`
	// Fixed thinking_budget for budget=mid (function='fixed').
	RecallBudgetFixedMid OptInt `json:"recall_budget_fixed_mid"`
	// Fixed thinking_budget for budget=high (function='fixed').
	RecallBudgetFixedHigh OptInt `json:"recall_budget_fixed_high"`
	// Ratio of max_tokens for budget=low (function='adaptive').
	RecallBudgetAdaptiveLow OptFloat64 `json:"recall_budget_adaptive_low"`
	// Ratio of max_tokens for budget=mid (function='adaptive').
	RecallBudgetAdaptiveMid OptFloat64 `json:"recall_budget_adaptive_mid"`
	// Ratio of max_tokens for budget=high (function='adaptive').
	RecallBudgetAdaptiveHigh OptFloat64 `json:"recall_budget_adaptive_high"`
	// Floor for the adaptive function (after clamping).
	RecallBudgetMin OptInt `json:"recall_budget_min"`
	// Ceiling for the adaptive function (after clamping).
	RecallBudgetMax OptInt `json:"recall_budget_max"`
	// Enable audit logging for this bank (overrides the server default).
	AuditLogEnabled OptBool `json:"audit_log_enabled"`
	// Persist raw source text (documents.original_text / chunks.chunk_text). Set false to keep only
	// derived facts.
	StoreDocumentText OptBool `json:"store_document_text"`
	// Automatically consolidate observations after retain.
	EnableAutoConsolidation OptBool `json:"enable_auto_consolidation"`
	// Max memory units fed into a single consolidation round.
	ConsolidationMaxMemoriesPerRound OptInt `json:"consolidation_max_memories_per_round"`
	// Number of consolidation LLM batches processed concurrently.
	ConsolidationLlmParallelism OptInt `json:"consolidation_llm_parallelism"`
	// Include raw chunks in recall results.
	RecallIncludeChunks OptBool `json:"recall_include_chunks"`
	// Max tokens of results returned by recall.
	RecallMaxTokens OptInt `json:"recall_max_tokens"`
	// Max tokens of raw chunks returned by recall (when recall_include_chunks is set).
	RecallChunksMaxTokens OptInt `json:"recall_chunks_max_tokens"`
	// Memory Defense policy for this bank (validated against the DefensePolicy schema on write).
	MemoryDefense OptBankTemplateConfigMemoryDefense `json:"memory_defense"`
}

