// Request to run fact extraction ONLY (no resolution/links/embeddings/persistence).
//
// Every field below the content/context/date is a prompt-affecting override applied just for this call
// — used to preview what a candidate retain mission (or any extraction setting) would extract,
// without changing the bank. Unset (null) fields fall back to the bank's resolved config.
// Ref: #/components/schemas/DryRunExtractRequest
type DryRunExtractRequest struct {
	// The raw content to extract facts from. Either a plain string, or an ordered list of content blocks
	// (text, image, file) so images/attachments sit inline where they actually appear.
	Content Content `json:"content"`
	// Optional context about the content.
	Context OptString `json:"context"`
	// Reference timestamp for resolving relative times (ISO 8601).
	Timestamp OptDateTime `json:"timestamp"`
	// Deprecated: describe the speaker in `context` instead. Narrator override (memory owner) primed in
	// the prompt; still honored for backwards compatibility.
	//
	// Deprecated: schema marks this property as deprecated.
	AgentName OptString `json:"agent_name"`
	// Name of a retain strategy to extract under (a key of the bank's `retain_strategies`). Omit it and
	// the bank's `retain_default_strategy` applies, exactly as it does for a retain that names none.
	Strategy                 OptString `json:"strategy"`
	RetainMission            OptString `json:"retain_mission"`
	RetainExtractionMode     OptString `json:"retain_extraction_mode"`
	RetainCustomInstructions OptString `json:"retain_custom_instructions"`
	RetainExtractCausalLinks OptBool   `json:"retain_extract_causal_links"`
	RetainChunkSize          OptInt    `json:"retain_chunk_size"`
	// Controlled vocabulary for entity labels (overrides the bank's config for this call).
	EntityLabels          []LabelGroupInput `json:"entity_labels"`
	EntitiesAllowFreeForm OptBool           `json:"entities_allow_free_form"`
	LlmOutputLanguage     OptString         `json:"llm_output_language"`
}

