// Content block type ('image' or 'file').
type ExtractedFactAttachmentType string

const (
	ExtractedFactAttachmentTypeImage ExtractedFactAttachmentType = "image"
	ExtractedFactAttachmentTypeFile  ExtractedFactAttachmentType = "file"
)

// AllValues returns all ExtractedFactAttachmentType values.
func (ExtractedFactAttachmentType) AllValues() []ExtractedFactAttachmentType {
	return []ExtractedFactAttachmentType{
		ExtractedFactAttachmentTypeImage,
		ExtractedFactAttachmentTypeFile,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s ExtractedFactAttachmentType) MarshalText() ([]byte, error) {
	switch s {
	case ExtractedFactAttachmentTypeImage:
		return []byte(s), nil
	case ExtractedFactAttachmentTypeFile:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *ExtractedFactAttachmentType) UnmarshalText(data []byte) error {
	switch ExtractedFactAttachmentType(data) {
	case ExtractedFactAttachmentTypeImage:
		*s = ExtractedFactAttachmentTypeImage
		return nil
	case ExtractedFactAttachmentTypeFile:
		*s = ExtractedFactAttachmentTypeFile
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

