// Single memory item for retain.
// Ref: #/components/schemas/MemoryItem
type MemoryItem struct {
	// The raw content to retain. Either a plain string, or an ordered list of content blocks so images sit
	// inline where they actually appear:
	//
	// [{"type": "text", "text": "click the button shown:"}, {"type": "image", "source": {"type": "base64",
	// "media_type": "image/png", "data": "..."}}, {"type": "text", "text": "...then reconnect."}]
	//
	// The block form requires a vision-capable retain LLM; a retain carrying images against a text-only
	// model is rejected rather than silently dropping them. A single text block is equivalent to the plain
	// string form.
	Content Content `json:"content"`
	// When the content occurred. Accepts an ISO 8601 datetime string (e.g. '2024-01-15T10:30:00Z'),
	// null/omitted (defaults to now), or the special string 'unset' to explicitly store without any
	// timestamp (use this for timeless content such as fictional documents or static reference material).
	Timestamp OptDateTime           `json:"timestamp"`
	Context   OptString             `json:"context"`
	Metadata  OptMemoryItemMetadata `json:"metadata"`
	// Optional document ID for this memory item. Provide a distinct document_id per source document —
	// items sharing a document_id are grouped into the same document. Auto-generated when omitted: if no
	// item in the request has one, they all share one generated document (a request split into parts for
	// size gets one per part); otherwise each item without one gets its own.
	DocumentID OptString `json:"document_id"`
	// Optional entities to combine with auto-extracted entities.
	Entities []EntityInput `json:"entities"`
	// Whether the names in 'entities' are resolved against the entities already in the bank. True
	// (default) matches each name to a similar existing entity when it scores above the match threshold,
	// so a name close to one already in the bank may resolve to that one instead of the one you wrote.
	// False takes your names literally — an existing entity is reused only on a case-insensitive name
	// match, any other name creates a new entity, and your names are never merged with each other. This
	// applies only to the entities you supply here; auto-extracted entities are always resolved, since
	// they are the extractor's guess at a name rather than yours. Ignored when 'entities' is omitted.
	ResolveEntities OptBool `json:"resolve_entities"`
	// Optional tags for visibility scoping. Memories with tags can be filtered during recall.
	Tags []string `json:"tags"`
	// How to scope observations during consolidation. 'per_tag' runs one consolidation pass per individual
	// tag, creating separate observations for each tag. 'combined' (default) runs a single pass with all
	// tags together. 'shared' runs a single pass over one global, untagged scope, so memories consolidate
	// together regardless of their tags — useful for deduplicating across volatile per-call provenance
	// tags (e.g. per-session ids) while keeping those tags on the source facts. A list of tag lists runs
	// one pass per inner list, giving full control over which combinations to use.
	ObservationScopes [][]string `json:"observation_scopes"`
	// Named retain strategy for this item. Overrides the bank's default strategy for this item only.
	// Strategies are defined in the bank config under 'retain_strategies'.
	Strategy OptString `json:"strategy"`
	// How to handle an existing document with the same document_id. 'replace' (default) deletes old data
	// and reprocesses from scratch. 'append' concatenates new content to the existing document text and
	// reprocesses.
	UpdateMode OptMemoryItemUpdateMode `json:"update_mode"`
}

