// How to handle an existing document with the same document_id. 'replace' (default) deletes old data
// and reprocesses from scratch. 'append' concatenates new content to the existing document text and
// reprocesses.
type MemoryItemUpdateMode string

const (
	MemoryItemUpdateModeReplace MemoryItemUpdateMode = "replace"
	MemoryItemUpdateModeAppend  MemoryItemUpdateMode = "append"
)

// AllValues returns all MemoryItemUpdateMode values.
func (MemoryItemUpdateMode) AllValues() []MemoryItemUpdateMode {
	return []MemoryItemUpdateMode{
		MemoryItemUpdateModeReplace,
		MemoryItemUpdateModeAppend,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s MemoryItemUpdateMode) MarshalText() ([]byte, error) {
	switch s {
	case MemoryItemUpdateModeReplace:
		return []byte(s), nil
	case MemoryItemUpdateModeAppend:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *MemoryItemUpdateMode) UnmarshalText(data []byte) error {
	switch MemoryItemUpdateMode(data) {
	case MemoryItemUpdateModeReplace:
		*s = MemoryItemUpdateModeReplace
		return nil
	case MemoryItemUpdateModeAppend:
		*s = MemoryItemUpdateModeAppend
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

