// The time window a refresh read memories from.
// Ref: #/components/schemas/MentalModelRefreshWindow
type MentalModelRefreshWindow struct {
	// Lower bound on when a memory last changed. Set only in delta mode, where it is the model's
	// last_memory_seen_at — so a delta refresh only sees memories written or edited since the newest one
	// the previous refresh saw.
	CreatedAfter OptDateTime `json:"created_after"`
	// Database-time snapshot bounding the refresh. Memories written or edited after this are not read, so
	// they stay newer than the persisted watermark and are caught by the next refresh.
	CreatedBefore time.Time `json:"created_before"`
	// The last_memory_seen_at a real refresh would persist: the newest in-scope memory visible at the
	// snapshot, not now(). Null means no in-scope memory was visible.
	Watermark OptDateTime `json:"watermark"`
}

