// Response model for a mental model (stored reflect response).
// Ref: #/components/schemas/MentalModelResponse
type MentalModelResponse struct {
	ID          string    `json:"id"`
	BankID      string    `json:"bank_id"`
	Name        string    `json:"name"`
	SourceQuery OptString `json:"source_query"`
	// The mental model content as well-formatted markdown (auto-generated from reflect endpoint).
	Content   OptString                   `json:"content"`
	Tags      []string                    `json:"tags"`
	MaxTokens OptInt                      `json:"max_tokens"`
	Trigger   OptMentalModelTriggerOutput `json:"trigger"`
	// When a refresh last finished for this model — wall-clock, in ISO format. Advances on every refresh
	// that completes, including one that found nothing new and preserved the content, and on a direct edit
	// of `content`. A refresh that failed leaves it alone. This is the field to answer 'have I already
	// refreshed this?'; it says nothing about whether the model is behind the data, which is
	// `last_memory_seen_at` / `is_stale`.
	LastRefreshedAt OptString `json:"last_refreshed_at"`
	// How far through the bank's memories this model is written — the newest in-scope memory the last
	// refresh saw, in ISO format. Stands still when nothing in the model's scope has been written, however
	// often it is refreshed. At or after the bank's `last_memory_write_at` (GET /stats) the model is
	// provably up to date; when it is older, `is_stale` settles it against the model's own scope. Null for
	// a model no refresh has stamped yet.
	LastMemorySeenAt OptString `json:"last_memory_seen_at"`
	// When this model's most recent refresh failed, in ISO format, or null when the last one succeeded.
	// While this is set the automatic triggers (`refresh_after_consolidation`, `refresh_cron`) skip the
	// model — a refresh that cannot succeed is not retried on every tick. An explicit refresh still
	// runs, and a successful one clears this. The failure itself, with its reason, is in the model's
	// history.
	LastRefreshFailedAt OptString `json:"last_refresh_failed_at"`
	CreatedAt           OptString `json:"created_at"`
	// Full reflect API response payload including based_on facts and observations.
	ReflectResponse OptMentalModelResponseReflectResponse `json:"reflect_response"`
	// True when memories matching this mental model's tag/fact_type scope have been written since
	// last_memory_seen_at — the same check that decides whether a scheduled refresh does any work, so a
	// model flagged here is one a refresh would actually rewrite. Populated on both the single read and
	// the list. Deletions are not observed: removing an in-scope memory leaves no write behind, so it does
	// not raise this flag.
	IsStale OptBool `json:"is_stale"`
}

