// Facts the document cited that no longer exist, and what was done about them.
//
// A retraction is the one refresh input that is invisible in every other report: the fact is gone from
// the bank, so it appears in no recall, no tool call, and no supporting-fact list. Without this, a
// refresh that quietly deleted a paragraph — or quietly declined to — leaves no evidence of why.
// Ref: #/components/schemas/MentalModelRetraction
type MentalModelRetraction struct {
	// Ids the document's based_on cites that no longer exist in the bank.
	FactIds []string `json:"fact_ids"`
	// What those facts said, as the document recorded them. The rows themselves are gone — an
	// observation swept away with its source keeps no history — so this copy is the only surviving
	// record.
	FactTexts []string `json:"fact_texts"`
	// Whether the pass that removes them ran to completion (zero edits still counts).
	Applied bool `json:"applied"`
	// Why removal was postponed, when it was. Re-ingested facts return under new ids once consolidation
	// catches up, so a retraction seen while facts are still pending is not acted on — removing content
	// before the replacements land would delete claims that are still true.
	DeferredReason OptString `json:"deferred_reason"`
}

