// Trigger settings for a mental model.
//
// A refresh is not an ad-hoc reflect with different arguments: it synthesizes a whole document, so it
// wants its own retrieval and iteration settings. This trigger is therefore the only source for them
// — a bank's `reflect_default_options` deliberately does not reach a refresh. The per-bank default
// for these fields is `knowledge_page_default_trigger`, which is merged over this same shape when a
// page is created.
// Ref: #/components/schemas/MentalModelTrigger-Input
type MentalModelTriggerInput struct {
	// How many agent iterations a refresh may spend, as a multiple of reflect_max_iterations: 'low' halves
	// it, 'mid' keeps it, 'high' doubles it. A refresh is the heaviest reflect there is — it writes a
	// whole document, and with exclude_mental_models it must read raw facts first — so null means 'mid',
	// not the 'low' an ad-hoc reflect defaults to.
	Budget OptBudget `json:"budget"`
	// Refresh mode. 'full' (default) regenerates the mental model content from scratch on each refresh.
	// 'delta' performs surgical edits against the existing content: unchanged sections are preserved
	// byte-for-byte, stale content is removed, new content is added. If the mental model has no existing
	// content, or if the source_query has changed since the last refresh, delta mode falls back to a full
	// regeneration automatically.
	Mode OptMentalModelTriggerInputMode `json:"mode"`
	// If true, refresh this mental model after observations consolidation (real-time mode).
	RefreshAfterConsolidation OptBool `json:"refresh_after_consolidation"`
	// Cron expression (UTC, standard 5-field syntax, e.g. '0 3 * * *' for daily at 03:00 UTC) for
	// refreshing this mental model on a fixed schedule. Mutually exclusive with
	// refresh_after_consolidation — a model refreshes either after consolidation or on a cron schedule,
	// not both. A scheduled refresh only runs when the model is stale (new memories in its scope since the
	// last refresh); if nothing changed, the tick is skipped to avoid a wasted LLM call. null = no
	// schedule.
	RefreshCron OptString `json:"refresh_cron"`
	// Minimum seconds between two automatic refreshes of this mental model. A triggered refresh that
	// arrives sooner is not dropped: it is queued and parked until the window expires, and every further
	// trigger in the meantime folds into that one queued refresh, so a burst of retains costs one refresh
	// instead of one per retain. Applies to both refresh_after_consolidation and refresh_cron. Explicit
	// refreshes (API, MCP, control plane) ignore it and run immediately. 0 disables the floor for this
	// model; null falls back to the bank/global mental_model_min_refresh_interval_seconds setting (itself
	// 0 by default, i.e. no floor).
	MinRefreshIntervalSeconds OptInt `json:"min_refresh_interval_seconds"`
	// Filter which fact types are retrieved during reflect. None means all types (world, experience,
	// observation).
	FactTypes []MentalModelTriggerInputFactTypesItem `json:"fact_types"`
	// If true, exclude all mental models from the reflect loop (skip search_mental_models tool).
	ExcludeMentalModels OptBool `json:"exclude_mental_models"`
	// Exclude specific mental models by ID from the reflect loop.
	ExcludeMentalModelIds []string `json:"exclude_mental_model_ids"`
	// Override how the model's tags filter memories during refresh. If not set, defaults to 'all_strict'
	// when the model has tags (security isolation) or 'any' when the model has no tags. Under 'all_strict'
	// a memory must carry EVERY one of the model's tags and untagged memories are excluded, which is why a
	// model tagged with labels its memories do not carry refreshes to empty content. Set to 'all' to keep
	// requiring the tags while including untagged memories, or to 'any' to include untagged memories
	// alongside any single tag match. Staleness ignores that widening: an untagged write never marks a
	// tagged model stale, in any mode — only a write that matches the model's tags does.
	TagsMatch OptMentalModelTriggerInputTagsMatch `json:"tags_match"`
	// Compound boolean tag expressions to use during refresh instead of the model's own tags. When set,
	// these tag groups are passed to reflect and the model's flat tags are NOT used for filtering.
	// Supports nested and/or/not expressions for complex tag-based scoping.
	TagGroups []MentalModelTriggerInputTagGroupsItem `json:"tag_groups"`
	// Override whether the internal recall used during refresh returns raw chunk text. None means use the
	// bank/global config default (recall_include_chunks).
	IncludeChunks OptBool `json:"include_chunks"`
	// Override the token budget for facts returned by the internal recall during refresh. None means use
	// the bank/global config default (recall_max_tokens).
	RecallMaxTokens OptInt `json:"recall_max_tokens"`
	// Override the token budget for raw chunks returned by the internal recall during refresh. None means
	// use the bank/global config default (recall_chunks_max_tokens).
	RecallChunksMaxTokens OptInt `json:"recall_chunks_max_tokens"`
	// Override the token budget for the refresh's search_observations calls. Observation evidence is often
	// the largest contributor to the reflect context; lowering it trades the lowest-ranked observations
	// for a smaller LLM context. null means the shipped 5000.
	ReflectSearchObservationsMaxTokens OptInt `json:"reflect_search_observations_max_tokens"`
	// Override whether search_observations attaches resolved entity names to each observation. Entities
	// can be more than half the serialized tool payload; turning them off keeps the same observations and
	// ranking with a much smaller context. null means enabled.
	ReflectSearchObservationsIncludeEntities OptBool `json:"reflect_search_observations_include_entities"`
	// Optional JSON Schema for structured output. When set, each refresh runs the same structured-output
	// extraction as reflect's response_schema and stores the parsed result under
	// reflect_response.structured_output alongside the markdown content.
	ResponseSchema OptMentalModelTriggerInputResponseSchema `json:"response_schema"`
	// If true, every refresh of this mental model records how it reached its result under
	// reflect_response.trace: the mode it ran in and why, the resolved scope and time window, how many
	// facts retrieval returned versus how many the agent used, the tool and LLM calls, and any delta
	// operations. Only the latest refresh's trace is kept. This is the only way to diagnose a cron- or
	// consolidation-driven refresh after the fact, since no human sees those run. Tool outputs are reduced
	// to result counts to keep the stored trace bounded; use LLM request tracing for raw prompts and
	// responses.
	KeepTrace OptBool `json:"keep_trace"`
}

