// Optional per-stage score floors for recall. Every floor is inclusive (`>=`).
//
// The four floors act at two different levels, and the distinction decides what a returned result is
// guaranteed to satisfy.
//
// `semantic` and `keyword` are retrieval-level cutoffs pushed into their own SQL arm (overriding the
// global `semantic_min_similarity` / `bm25_min_score` config for this request), so they prune weak
// matches before fusion. Each one constrains only the arm it names. Recall fuses four arms —
// semantic, keyword, graph and temporal — and a result reaches the response if any arm surfaced it,
// so a returned result may legitimately carry `null` for a stage it was not surfaced by, and results
// reached through the graph or temporal arm carry neither `semantic` nor `keyword`. A non-null score
// always clears its floor — the gap is only ever a `null`. Setting both does not restrict the
// response to results that clear both: they are not a predicate over each fused result. This is
// deliberate — an intersection would discard the strong single-arm matches that hybrid retrieval
// exists to find (a paraphrase with no lexical overlap, an exact identifier the embedding scores
// poorly).
//
// `reranker` and `final` are post-query filters applied to every scored result after fusion and
// reranking, so these are per-result predicates: a returned result always clears them. Use them, not
// the retrieval floors, to make recall abstain on low-confidence queries.
//
// Any field left None imposes no floor; all-None (the default) means no score filtering.
// Ref: #/components/schemas/MinScores
type MinScores struct {
	// Retrieval-level, semantic arm only: minimum vector similarity (0-1). A result the semantic arm did
	// not surface reports `semantic: null` and is unaffected by this floor.
	Semantic OptFloat64 `json:"semantic"`
	// Retrieval-level, keyword arm only: minimum keyword/full-text (BM25) score. A result the keyword arm
	// did not surface reports `keyword: null` and is unaffected by this floor.
	Keyword OptFloat64 `json:"keyword"`
	// Post-query: minimum normalized reranker score (0-1). Applied to every returned result. Rejected with
	// HTTP 400 when the reranker scores by rank position (TypeSafe), since a floor would only keep a fixed
	// share of the results.
	Reranker OptFloat64 `json:"reranker"`
	// Post-query: minimum final ranking score. Applied to every returned result.
	Final OptFloat64 `json:"final"`
}

