// Request model for recall endpoint.
// Ref: #/components/schemas/RecallRequest
type RecallRequest struct {
	Query string `json:"query"`
	// List of fact types to recall: 'world', 'experience', 'observation'. Defaults to all fact types if
	// not specified.
	Types []string `json:"types"`
	// When recalling raw facts ('world'/'experience') together with 'observation', drop any raw fact that
	// an observation in the results was consolidated from, so the observation supersedes it and you don't
	// get duplicate content. The freed slots are backfilled with the next results, keeping the result
	// count at the requested budget. Disabled by default; set to true to enable. No effect unless
	// 'observation' and at least one raw type are both requested.
	PreferObservations OptBool   `json:"prefer_observations"`
	Budget             OptBudget `json:"budget"`
	MaxTokens          OptInt    `json:"max_tokens"`
	Trace              OptBool   `json:"trace"`
	// ISO format date string (e.g., '2023-05-30T23:40:00'). Used as the query-time anchor for relative
	// temporal expressions and recency scoring.
	QueryTimestamp OptString `json:"query_timestamp"`
	// Options for including additional data (entities are included by default).
	Include OptIncludeOptions `json:"include"`
	// Filter memories by tags. If not specified, all memories are returned. Omitting tags (or passing [])
	// together with tags_match='exact' filters to untagged/global observations only (the scope written by
	// observation_scopes='shared').
	Tags []string `json:"tags"`
	// How to match tags: 'any' (OR, includes untagged), 'all' (AND, includes untagged), 'any_strict' (OR,
	// excludes untagged), 'all_strict' (AND, excludes untagged), 'exact' (set-equality on the full scope,
	// excludes untagged). With 'exact' and no tags (or []), the empty global scope is selected and only
	// untagged memories match.
	TagsMatch OptRecallRequestTagsMatch `json:"tags_match"`
	// Compound tag filter using boolean groups. Groups in the list are AND-ed. Each group is a leaf {tags,
	// match} or compound {and: [...]}, {or: [...]}, {not: ...}. A leaf may set resolve='fuzzy' to match
	// its tags against the bank's tags by trigram similarity instead of literally, so a query that says
	// 'typsecript' still reaches memories tagged 'typescript'.
	TagGroups []RecallRequestTagGroupsItem `json:"tag_groups"`
	// Optional per-stage score floors, each inclusive (`>=`). `semantic` and `keyword` are retrieval-level
	// cutoffs pushed into the SQL arm they name (overriding the global similarity/BM25 minimums for this
	// request), and constrain only that arm: recall fuses four arms (semantic, keyword, graph, temporal)
	// and returns a result surfaced by any of them, so a returned result reports null for a stage that did
	// not surface it (a non-null score always clears its floor). Setting both therefore does not restrict
	// the response to results clearing both. `reranker` and `final` are post-ranking filters applied to
	// every scored result, so those floors are guaranteed by each result returned — use them for query
	// abstention. Any field left unset imposes no floor; omitting `min_scores` entirely (the default)
	// applies no score filtering. Use with care — the reranker's absolute scores are not calibrated
	// across queries (a clearly-relevant match may score ~0.001 even though it is ranked first).
	MinScores OptMinScores `json:"min_scores"`
	// Window for the temporal retrieval arm, supplied instead of extracting dates from `query`. Set this
	// when you already know the range you mean — a date picker, or an agent that resolved 'last quarter'
	// itself — and recall will skip parsing the query text for dates. This ranks, it does not filter:
	// the temporal arm surfaces memories whose own dates (`mentioned_at`, `occurred_start`,
	// `occurred_end`) fall inside the window so they rank higher, while the semantic, keyword and graph
	// arms are unaffected — so memories dated outside the window are still returned. Ignored when the
	// bank has temporal retrieval disabled.
	TemporalWindow OptTemporalWindow `json:"temporal_window"`
}

