// Request model for reflect endpoint.
// Ref: #/components/schemas/ReflectRequest
type ReflectRequest struct {
	// Token budget for reflect's search_observations tool when the model names none. Observation evidence
	// is often the largest contributor to the reflect context; lowering it trades the lowest-ranked
	// observations for a smaller LLM context. None means use the shipped default (5000).
	ReflectSearchObservationsMaxTokens OptInt `json:"reflect_search_observations_max_tokens"`
	// Whether search_observations attaches resolved entity names to each observation. Entities can be more
	// than half the serialized tool payload; turning them off keeps the same observations and ranking with
	// a much smaller context. None means enabled.
	ReflectSearchObservationsIncludeEntities OptBool   `json:"reflect_search_observations_include_entities"`
	Query                                    string    `json:"query"`
	Budget                                   OptBudget `json:"budget"`
	// DEPRECATED: Additional context is now concatenated with the query. Pass context directly in the
	// query field instead. If provided, it will be appended to the query for backward compatibility.
	//
	// Deprecated: schema marks this property as deprecated.
	Context OptString `json:"context"`
	// Maximum tokens for the response.
	MaxTokens OptInt `json:"max_tokens"`
	// Options for including additional data (disabled by default).
	Include OptReflectIncludeOptions `json:"include"`
	// Optional JSON Schema for structured output. When provided, the response will include a
	// 'structured_output' field with the LLM response parsed according to this schema.
	ResponseSchema OptReflectRequestResponseSchema `json:"response_schema"`
	// Scope raw facts, observations, mental models, and tagged directives during reflection. With no tags,
	// memory retrieval is unfiltered while only untagged/global directives are loaded. Use tags=[] with
	// tags_match='exact' to select the untagged/global scope.
	Tags []string `json:"tags"`
	// How to match tags: 'any' (OR, includes untagged), 'all' (AND, includes untagged), 'any_strict' (OR,
	// excludes untagged), 'all_strict' (AND, excludes untagged), or 'exact' (set equality). Untagged
	// directives remain global in every mode.
	TagsMatch OptReflectRequestTagsMatch `json:"tags_match"`
	// Compound tag filter using boolean groups. Groups in the list are AND-ed. Each group is a leaf {tags,
	// match} or compound {and: [...]}, {or: [...]}, {not: ...}. Mutually exclusive with tags. A leaf may
	// set resolve='fuzzy' to match its tags against the bank's tags by trigram similarity instead of
	// literally, so a query that says 'typsecript' still reaches memories tagged 'typescript'.
	TagGroups []ReflectRequestTagGroupsItem `json:"tag_groups"`
	// Apply every active directive regardless of tags. By default directives are scoped like memories:
	// untagged directives always apply, and tagged directives apply only when the request's tags match
	// them. Set true to apply all active directives, ignoring tag scope.
	ApplyAllDirectives OptBool `json:"apply_all_directives"`
	// Filter which fact types are retrieved during reflect. None means all types (world, experience,
	// observation).
	FactTypes []ReflectRequestFactTypesItem `json:"fact_types"`
	// If true, exclude all mental models from the reflect loop (skip search_mental_models tool).
	ExcludeMentalModels OptBool `json:"exclude_mental_models"`
	// Exclude specific mental models by ID from the reflect loop.
	ExcludeMentalModelIds []string `json:"exclude_mental_model_ids"`
}

