// Request model for curating a single memory unit (edit / invalidate / revert).
//
// Provide `text` to correct the fact, and/or `state` to invalidate ('invalidated') or revert ('valid')
// it. `reason` is optional free text recorded on the memory. At least one of `text` or `state` must be
// set. Only world/experience facts can be curated; observations are derived.
// Ref: #/components/schemas/UpdateMemoryRequest
type UpdateMemoryRequest struct {
	// New fact text. Re-embeds the memory, drops its derived observations and links, and triggers
	// re-consolidation.
	Text OptString `json:"text"`
	// New context for the fact. '' clears it; omit to leave unchanged.
	Context OptString `json:"context"`
	// New occurred-range start (ISO 8601). '' clears it; omit to leave unchanged.
	OccurredStart OptString `json:"occurred_start"`
	// New occurred-range end (ISO 8601). '' clears it; omit to leave unchanged.
	OccurredEnd OptString `json:"occurred_end"`
	// Reclassify the fact: 'world' or 'experience'. Omit to leave unchanged.
	FactType OptString `json:"fact_type"`
	// Replace the fact's entities. How each name is matched to an entity is governed by
	// 'resolve_entities'. '[]' detaches all entities. Omit to leave unchanged.
	Entities []string `json:"entities"`
	// Whether the names in 'entities' are resolved against the entities already in the bank. True
	// (default) is what retain does: a similar existing entity is reused when it scores above the match
	// threshold, so a name close to one already in the bank may resolve to that one instead of the one you
	// wrote. False takes the names literally — an existing entity is reused only on a case-insensitive
	// name match, any other name creates a new entity, and names in the same request are never merged with
	// each other. Use False for hand-authored corrections, where the name you sent is the answer rather
	// than a guess. Ignored when 'entities' is omitted.
	ResolveEntities OptBool `json:"resolve_entities"`
	// Curation state: 'invalidated' to soft-retire the memory (excluded from recall/consolidation, links
	// and derived observations pruned, moved to the archive) or 'valid' to revert. Reversible.
	State OptString `json:"state"`
	// Optional free-text reason recorded when invalidating.
	Reason OptString `json:"reason"`
}

